import numpy as np

# Simulasi Partition Pruning: Evaluasi Efisiensi Range vs Hash Partitioning
class PartitionedTable:
    def __init__(self, partition_type="RANGE"):
        self.type = partition_type
        # Partisi fisik data: {partisi_id: list of records}
        self.partitions = {}

    def insert_range(self, year, record):
        if year not in self.partitions:
            self.partitions[year] = []
        self.partitions[year].append(record)

    def query_with_pruning(self, target_year):
        # Optimizer hanya mengakses partisi yang relevan
        if target_year in self.partitions:
            scanned_records = len(self.partitions[target_year])
            total_records = sum(len(p) for p in self.partitions.values())
            return scanned_records, total_records, [target_year]
        return 0, sum(len(p) for p in self.partitions.values()), []

table = PartitionedTable(partition_type="RANGE")
# Ingesti data 3 tahun transaksi
for y in [2024, 2025, 2026]:
    for i in range(100_000):
        table.insert_range(y, {"id": f"{y}_{i}", "amount": 50.0})

scanned, total, pruned_parts = table.query_with_pruning(2026)
print(f"Hasil Evaluasi Partition Pruning (Total Data: {total:,} Baris):")
print(f"  Target Filter Kueri    : WHERE year = 2026")
print(f"  Partisi Fisik Disentuh : {pruned_parts} (Partisi 2024 dan 2025 dilewati penuh!)")
print(f"  Baris Dipindai di Disk : {scanned:,} baris ({scanned/total*100:.1f}% dari total tabel)")
print(f"  Reduksi Beban I/O Disk : {(1.0 - scanned/total)*100:.1f}% Penghematan I/O!")

import time

# Simulasi Incremental Materialized View Maintenance vs Full Re-computation
class IncrementalMaterializedView:
    def __init__(self):
        # Status Materialized View: {kategori: [sum_amount, count_items]}
        self.view_state = {}

    def initialize_view(self, initial_records):
        for cat, amt in initial_records:
            if cat not in self.view_state:
                self.view_state[cat] = [0.0, 0]
            self.view_state[cat][0] += amt
            self.view_state[cat][1] += 1

    def apply_delta_mutation(self, delta_records):
        # Inkremental: Hanya proses delta baru tanpa sentuh data lama!
        for cat, amt in delta_records:
            if cat not in self.view_state:
                self.view_state[cat] = [0.0, 0]
            self.view_state[cat][0] += amt
            self.view_state[cat][1] += 1

    def get_average(self, cat):
        if cat in self.view_state and self.view_state[cat][1] > 0:
            return self.view_state[cat][0] / self.view_state[cat][1]
        return 0.0

# 1 Juta Data Awal
initial_data = [("Elektronik", 500.0)] * 500_000 + [("Pakaian", 100.0)] * 500_000
mv = IncrementalMaterializedView()
mv.initialize_view(initial_data)

# 100 Data Delta Baru Datang
delta_data = [("Elektronik", 600.0)] * 100

t0 = time.perf_counter()
mv.apply_delta_mutation(delta_data)
dur_incremental_us = (time.perf_counter() - t0) * 1_000_000

print("Evaluasi Materialized View Inkremental (IVM):")
print(f"  Rerata Kategori Elektronik : Rp {mv.get_average('Elektronik'):.2f}")
print(f"  Durasi Update Inkremental : {dur_incremental_us:.2f} mikrodetik (Hanya memproses 100 baris delta!)")
print(f"  Akselerasi Kinerja         : Sub-milidetik, meniadakan pemindaian ulang 1,000,000 baris!")
